def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self.edges is None:
        raise NotImplementedError("Histogram edges are not defined.")
    if len(coord) != self.ndim:
        raise ValueError("`coord` length does not match histogram ndim.")
    if not all([x >= 0 for x in coord]):
        raise ValueError("`coord` must be a non-negative vector.")
    if not isinstance(weight, (int, float)):
        raise ValueError("`weight` must be a number.")
    i = 0
    for edge in self.edges:
        if coord[i] < edge:
            return
        elif coord[i] >= edge:
            i += 1
            if i == len(self.edges):
                return
    self.contents[i] += weight
    return self.contents[i]

