def generate_default_observer_schema(app):

    # Check if a custom observer schema has been specified for the application
    if app.spec.manifest.observer_schema is not None:
        return app.spec.manifest.observer_schema

    # If no custom schema has been specified, generate a default schema
    default_schema = {
        "kubernetes": "True", # Indicate that this schema has been generated automatically
        "namespace": "default", # Default namespace for observer
        "entity": [], # No default entities defined
    }

    # Loop through all Kubernetes resources present in the manifest
    for resource, info in app.spec.manifest.resources.items():

        # If the resource has no defined observer field, add a default observer
        if "observer" not in info.labels:
            default_schema["entity"].append({
                "apiVersion": info.apiVersion,
                "kind": info.kind,
                "name": info.metadata.name,
                "namespace": info.metadata.namespace,
            })

    # Return the default schema
    return default_schema

