def generate_default_observer_schema(app):
    if not app.spec.manifest or not app.spec.observers:
        raise ValueError("Invalid input: `spec.manifest` and `spec.observers` must be specified.")

    default_observer_schema = {}

    for resource in app.spec.manifest:
        if not resource.metadata.generate_from:
            raise ValueError(f"Invalid input: `generate_from` must be specified for resource {resource.metadata.name}.")

        if not resource.metadata.generate_from.observer:
            raise ValueError(f"Invalid input: `observer` must be specified for resource {resource.metadata.name}.")

        default_observer_schema[resource.metadata.name] = resource.metadata.generate_from.observer

    return default_observer_schema

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, Mapping):
        in_params = set(params.keys())
        out_params = {}
        for i, param in enumerate(in_params):
            out_params[f"@{i}"] = params[param]
        return sql, out_params
    elif isinstance(params, Sequence):
        out_params = {}
        for i, param in enumerate(params):
            out_params[f"@{i}"] = param
        return sql, out_params
    else:
        raise ValueError("Invalid parameter type")

def format(
	self,
	sql: AnyStr,
	params: Union[Dict[Union[str, int], Any], Sequence[Any]]
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
	# Check if the SQL query is a string or bytes
	if not isinstance(sql, (str, bytes)):
		raise ValueError("Invalid SQL query type")

	# Check if the parameters are a mapping or a sequence
	if not isinstance(params, (Dict, list)):
		raise ValueError("Invalid parameters type")

	# Convert the SQL query to use out-style parameters
	sql = sql.replace("@", "?")

	# Convert the parameters to a dictionary or list as required
	if isinstance(params, dict):
		params = {"?": value for key, value in params.items()}
	else:
		params = {"?": value for value in params}

	return sql, params

def formatmany(
	self,
	sql: AnyStr,
	many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
):
    formatted_sql, out_params = [], []
    for params in many_params:
        try:
            formatted_sql.append(self._formatone(sql, params))
            out_params.append(self._convert_params(params, self._parameters.out_style))
        except Exception as e:
            continue
    return formatted_sql, out_params

def _formatone(
	self,
	sql: AnyStr,
	params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> AnyStr:
    if self._parameters.in_style == 'named':
        return sql.format(*params.values())
    else:
        return sql.format(*params)

def _convert_params(
	self,
	params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	out_type: str
) -> Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]:
    if out_type == 'list':
        return list(params.values())
    elif out_type == 'dict':
        return dict([(k, v) for k, v in enumerate(params)])
    else:
        raise ValueError("Invalid out_type: %s" % out_type)

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
	) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		# check if in_style is "named"
		if self.in_style == "named":
			# check if each params is a Mapping
			if not all(isinstance(params, Mapping) for params in many_params):
				raise TypeError("Expected Iterable[Dict[Union[str, int], Any]]")
			# convert each params to out style
			out_params = []
			for params in many_params:
				out_params.append({k: params[k] for k in sorted(params.keys(), key=lambda k: k.lower())})
		# check if in_style is "ordinal"
		elif self.in_style == "ordinal":
			# check if each params is a Sequence
			if not all(isinstance(params, Sequence) for params in many_params):
				raise TypeError("Expected Iterable[Sequence[Any]]")
			# convert each params to out style
			out_params = []
			for params in many_params:
				out_params.append(list(params))
		# format the sql with each out_param
		formatted_sql = self._format(sql, out_params)
		return formatted_sql, out_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    out_style_params = []
    formatted_sql = sql
    for params in many_params:
        if isinstance(params, Mapping):
            params = [params]
        out_style_params.append(self.format(params))
    return formatted_sql, out_style_params

