def get_logical_path_map(inventory, version):
    logical_path_map = {}
    for logical_path, versioned_file in inventory.items():
        if not versioned_file.is_file:
            continue
        if versioned_file.version == version:
            logical_path_map[logical_path] = set([versioned_file.path])
            continue
        if versioned_file.ref is not None:
            logical_path_map[logical_path].add(versioned_file.ref.path)
