            logical_path_map[logical_path].add(versioned_file.path)
    return logical_path_map

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    version_inventory = inventory[version]
    for content_file in version_inventory:
        logical_path = content_file.logical_path
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(content_file)
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk."""
    logical_path_map = {}

    for state_name, state in inventory.items():
        if state.get('version') == version:
            for content_file in state.get('files'):
                logical_path = content_file.get('logical_path')

                if logical_path not in logical_path_map:
                    logical_path_map[logical_path] = set()

                if content_file not in logical_path_map[logical_path]:
                    logical_path_map[logical_path].add(content_file)

    return logical_path_map

