def _group_files_by_xml_filename(xml_filename, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    results = {}
    for file in files:
        if file.endswith(".xml"):
            xml_basename = os.path.basename(file).split(".xml")[0]
            if xml_basename in results:
                results[xml_basename].append(file)
            else:
                results[xml_basename] = [file]
    return results

