            elif os.path.isdir(f):
                # Looks like a directory
                return "directory"
            else:
                # Some other file type
                return "file"

def find_path_type(path):
    try:
        namaste_file = f"{path}namaste"
        with open(namaste_file, "r") as f:
            root_dir = f.readline().strip()
            if root_dir == "ocfl-spec/1.0":
                return "root"
            elif root_dir == "ocfl-object":
                return "object"
            elif root_dir == "file":
                return "file"
            else:
                return f"Unknown error: {root_dir}"
    except FileNotFoundError:
        return "file"
    except Exception as e:
        return f"Unknown error: {e}"

