def bash_completion():
    import argparse, shlex, sys
    parser = argparse.ArgumentParser(prog='borgmatic')
    subparsers = parser.add_subparsers()

    # Add all subparsers as arguments to the `borgmatic` command
    for subparser in subparsers.choices.values():
        group_name = subparser.prog.replace('-', '_')
        parser.add_argument(f'{group_name}', nargs='*', help=subparser.description)

    words = []
    for option in parser._optionals._actions:
        if option.choices is not None:
            words.extend(option.choice_list)

    # Split parse results and retrieve arguments and options
    parse_results = shlex.split(sys.stdin.read())
    if len(parse_results) == 0:
        return
    command = parse_results[0]
    args = parse_results[1:]
    opts = dict(zip(args, args[1:]))

    # If no arguments are provided, treat as a request for a list of available commands
    if command == 'borgmatic':
        return ' '.join(parser._optionals._actions_map.keys())

    # If option to initialize a repository is provided, treat as a list of repository options
    if opts.get('init') is not None:
        options = ' '.join(parser.get_prog_name() + ' ' + parser._optionals._actions_map['init'].aliases[0] + ' ' + parser._optionals._actions_map['init'].metavar)
        return options

    # If option to create a backup is provided, treat as a list of backup options
    if opts.get('backup') is not None:
        options = ' '.join(parser.get_prog_name() + ' ' + parser._optionals._actions_map['backup'].aliases + ' ' + parser._optionals._actions_map['backup'].metavar)
        return options

    # Otherwise, return the words from argument and option parsing
    return ' '.join(words)

