def vertex3tuple(vertices):
    """
    Generates 3 points for each vertex of the polygon, including the vertex itself and the 2 points on either side of it
    """
    points = []
    for i in range(len(vertices)):
        point1 = [vertices[i-1], vertices[i], vertices[i+1]]
        try:
            point2 = [vertices[i-2], vertices[i-1], vertices[i]]
        except IndexError:
            point2 = None
        try:
            point3 = [vertices[i], vertices[i+1], vertices[i+2]]
        except IndexError:
            point3 = None
        points.append(point1)
        points.append(point2)
        points.append(point3)
    return points

