    if not isinstance(string, str):
        raise ValueError("string must be a string")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")

    if len(string) == 0:
        return 0

    result = 0
    power = 1
    for char in reversed(string):
        if char not in alphabet:
