        if match:
            count = int(match.group(1))
            unit = match.group(2).lower()
            if unit == "days":
                return datetime.timedelta(days=count)
            elif unit == "weeks":
                return datetime.timedelta(weeks=count)
            elif unit == "months":
                return datetime.timedelta(days=count * 30)
            elif unit == "years":
                return datetime.timedelta(days=count * 365)
            else:
                raise ValueError(f"Unknown frequency unit: {unit}")
        else:
            raise ValueError(f"Invalid frequency: {frequency}")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    match = re.fullmatch(r"(?P<number>\d+) (?P<unit>(year|years|month|months|week|weeks|day|days|hour|hours|minute|minutes|second|seconds))", frequency)
    if not match:
        raise ValueError("Invalid frequency format. Unit must be one of year, year, month, month, week, weeks, day, days, hour, hours, minute, minutes, second, seconds")
    number = int(match.group("number"))
    unit = match.group("unit")
    if unit in ["year", "years"]:
        return datetime.timedelta(days=365 * number)
    elif unit in ["month", "months"]:
        return datetime.timedelta(days=30 * number)
    elif unit in ["week", "weeks"]:
        return datetime.timedelta(weeks=number)
    elif unit in ["day", "days"]:
        return datetime.timedelta(days=number)
    elif unit in ["hour", "hours"]:
        return datetime.timedelta(hours=number)
    elif unit in ["minute", "minutes"]:
        return datetime.timedelta(minutes=number)
    elif unit in ["second", "seconds"]:
        return datetime.timedelta(seconds=number)
    else:
        raise ValueError(f"Invalid frequency unit: {unit}")

