def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    image_id, netloc, use_ssl = None, None, None
    url_info = urllib.parse.urlparse(image_href)
    if url_info.scheme == "file":
        file_path = url_info.path
        if file_path.startswith("/"):
            file_path = file_path[1:]
            image_id, netloc, use_ssl = file_path.split("/")
        else:
            image_id = file_path
    else:
        image_id = url_info.netloc
        if url_info.scheme == "https":
            use_ssl = True
    if not image_id or not netloc:
        raise ValueError(f"Invalid image href: {image_href}")
    return image_id, netloc, use_ssl

