def slice_file(self, path: str, recursive: bool = False, on_match: Optional[callable] = None) -> List[slice]:
    """Slice a file or directory tree into subfiles.

    Args:
        path: The path to the file or directory to slice.
        recursive: Whether to recursively search the directory for files to slice.
        on_match: A callable that will be called with the path of each matching file.

    Returns:
        A list of slices representing the subfiles.
    """

    if not isinstance(path, str):
        raise ValueError("path must be a string")
    if recursive and not isinstance(recursive, bool):
        raise ValueError("recursive must be a boolean")
    if on_match is not None and not callable(on_match):
        raise ValueError("on_match must be a callable")

    slices = []

    # if the path is a file, slice it and return
    if os.path.isfile(path):
        slices = [self._slice_file(path)]

    # if recursively is true and the path is a directory, slice all files in the directory tree
    if recursive:
        for root, dirs, files in os.walk(path):
            for file in files:
                file_path = os.path.join(root, file)
                slices.append(self._slice_file(file_path))

    # if on_match is not None, call it with the path(s) of the matching files
    if on_match is not None:
        for slice in slices:
            on_match(slice.path)

    return slices

