    elif document.startswith("{") and document.endswith("}"):
        # JSON style
        parsed_doc = json.loads(document)
    else:
        raise Exception("Invalid document format")

    # Ensure the output is a flat dictionary
    output = {}
    for key, value in parsed_doc.items():
        if isinstance(value, list) or isinstance(value, dict):
            for item in value:
                output[key] = item
        else:
            output[key] = value
    return output

