def list_of_file_names(settings_dirs, spec_option):
    """Create a list of file names from the specified directories and spec
    options.

    Args:
        settings_dirs (list): List of setting directories to search
        spec_option (str): The spec option to use
    Returns:
        list: A list of file names matching the specified options

    Raises:
        ValueError: If the settings_dirs or spec_option is not of the correct type

    Example:
        list_of_file_names(['dir1', 'dir2'], 'spec1')
    """
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    file_names = []

    for dir in settings_dirs:
        if os.path.isdir(dir):
            for root, _, files in os.walk(dir):
                for file in files:
                    if fnmatch.fnmatch(file, spec_option):
                        file_names.append(os.path.join(root, file))

    return file_names

